import {MOTION_KEY,validateMotionPack,mergeMotionPacks,PLACES,DIRECTIONS,FACES} from './motion-packs.js';
import {HANDSHAPE_NAMES} from './vendor/sign-avatar/sign-handshapes.js';
export function createMotionLibrary({getLanguage,onChange,onPreview,onPose,toast}){
 const $=id=>document.getElementById(id);let pack={version:1,motions:[]},phases=[];
 try{const saved=JSON.parse(globalThis.localStorage?.getItem(MOTION_KEY)||'null');if(saved)pack=validateMotionPack(saved);}catch{toast('Saved motions could not be loaded. Import your exported backup to restore them.');}
 const handPanel=(side)=>{const field=document.createElement('fieldset');field.innerHTML=`<legend>Signer’s ${side} hand</legend><label>Hand state<select id="motion-${side}-state"><option value="pose">Set pose</option><option value="rest">Rest</option></select></label><label>Handshape<select id="motion-${side}-shape"></select></label><label>Body location<select id="motion-${side}-place"></select></label><label>Finger direction<select id="motion-${side}-fingers"></select></label><label>Palm direction<select id="motion-${side}-palm"></select></label><label>Side offset (metres)<input id="motion-${side}-out" type="number" min="-0.55" max="0.55" step="0.01" value="0.15"></label><label>Vertical offset (metres)<input id="motion-${side}-up" type="number" min="-0.55" max="0.55" step="0.01" value="0"></label><label>Forward offset (metres)<input id="motion-${side}-forward" type="number" min="-0.55" max="0.55" step="0.01" value="0.2"></label>`;$('motion-hands').append(field);
  for(const [name,values] of [['shape',HANDSHAPE_NAMES],['place',PLACES],['fingers',DIRECTIONS],['palm',DIRECTIONS]])for(const value of values){const o=document.createElement('option');o.value=value;o.textContent=value;$(`motion-${side}-${name}`).append(o);}
  $(`motion-${side}-shape`).value='RELAXED';$(`motion-${side}-place`).value='sternum';$(`motion-${side}-fingers`).value='up';$(`motion-${side}-palm`).value='forward';if(side==='left')$(`motion-${side}-state`).value='rest';
 };
 handPanel('right');handPanel('left');for(const value of FACES){const o=document.createElement('option');o.value=value;o.textContent=value;$('motion-face').append(o);}
 function readHand(side){if($(`motion-${side}-state`).value==='rest')return 'rest';return {shape:$(`motion-${side}-shape`).value,at:{anchor:$(`motion-${side}-place`).value,out:Number($(`motion-${side}-out`).value),up:Number($(`motion-${side}-up`).value),forward:Number($(`motion-${side}-forward`).value)},fingers:$(`motion-${side}-fingers`).value,palm:$(`motion-${side}-palm`).value};}
 function readPhase(){return {t:Number($('motion-transition').value),hold:Number($('motion-hold').value),right:readHand('right'),left:readHand('left'),face:$('motion-face').value,head:{nod:Number($('motion-nod').value),turn:Number($('motion-turn').value),tilt:0}};}
 function draft(steps=phases){const speech={};if($('motion-narration').value.trim())speech[$('coach-language').value]=$('motion-narration').value.trim();return validateMotionPack({version:1,motions:[{language:getLanguage(),label:$('motion-label').value,source:$('motion-source').value,description:$('motion-description').value,reviewer:$('motion-reviewer').value,speech,phases:steps}]}).motions[0];}
 function persist(){try{localStorage.setItem(MOTION_KEY,JSON.stringify(pack));return true;}catch{toast('Storage is full or unavailable. Export your motions now; changes are in memory only.');return false;}}
 function refresh(){
  $('motion-language').textContent=getLanguage();const relevant=pack.motions.filter(m=>m.language===getLanguage());$('motion-count').textContent=`${relevant.length} personal motion(s) for this language · ${pack.motions.length} total on this device`;
  $('motion-list').replaceChildren();for(const m of relevant){const row=document.createElement('div');row.className='avatar-saved-row';const view=document.createElement('button');view.className='secondary';view.textContent=m.label+' · '+(m.reviewer?'review attributed to '+m.reviewer:'unreviewed');view.onclick=()=>onPreview(m.label,m.language,pack.motions);const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','Remove motion '+m.label);remove.onclick=()=>{pack.motions=pack.motions.filter(v=>v!==m);persist();refresh();onChange();};row.append(view,remove);$('motion-list').append(row);}
  $('motion-steps').replaceChildren();phases.forEach((p,i)=>{const li=document.createElement('li');li.textContent=`Step ${i+1}: right ${p.right==='rest'?'rest':p.right.shape}, left ${p.left==='rest'?'rest':p.left.shape} · ${p.t}s move, ${p.hold}s hold `;const remove=document.createElement('button');remove.textContent='Remove';remove.className='text-button';remove.onclick=()=>{phases.splice(i,1);refresh();};li.append(remove);$('motion-steps').append(li);});
 }
 const attempt=fn=>()=>{try{fn();}catch(e){toast(e.message);}};
 $('motion-preview-pose').onclick=attempt(()=>{const phase=readPhase();const m=draft([phase]);onPose(m.phases[0]);});
 $('motion-add-step').onclick=attempt(()=>{const phase=readPhase();draft([...phases,phase]);phases.push(phase);refresh();});
 $('motion-preview').onclick=attempt(()=>{const m=draft();onPreview(m.label,m.language,mergeMotionPacks(pack,{version:1,motions:[m]}).motions);});
 $('motion-save').onclick=attempt(()=>{const m=draft();pack=mergeMotionPacks(pack,{version:1,motions:[m]});const saved=persist();refresh();onChange();toast(saved?'Motion saved for '+getLanguage()+'. Review it with a fluent signer.':'Motion is available for this session. Export a backup.');});
 $('motion-reset').onclick=()=>{phases=[];refresh();};
 $('motion-import').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('Motion packs may be up to 1 MB.');const incoming=validateMotionPack(JSON.parse(await file.text()));pack=mergeMotionPacks(pack,incoming);const saved=persist();refresh();onChange();if(saved)toast(incoming.motions.length+' sourced motions imported. Review attribution is supplied by the pack author.');}catch(e){toast('Motion import failed: '+e.message);}finally{event.target.value='';}};
 $('motion-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(pack,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='SignVoice-motion-pack.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 refresh();return {get:()=>pack.motions,refresh,clear(){pack={version:1,motions:[]};phases=[];try{localStorage.removeItem(MOTION_KEY);}catch{}refresh();}};
}
